module TopModule (
  input clk,
  input j,
  input k,
  output reg Q
);
reg Qold;
  always @(posedge clk) begin
    if (j == 0) begin
      if (k == 0) begin
        Q <= Qold;
      end else begin
        Q <= 0;
      end
    end else begin
      if (k == 0) begin
        Q <= 1;
      end else begin
        Q <= ~Qold;
      end
    end
  end
  always @(posedge clk) begin
    Qold <= Q;
  end
endmodule

