module TopModule (
  input clk,
  input a,
  output reg q
);
always @(posedge clk) begin
    if (a) begin
      q <= 1;
    end else begin
      q <= 0;
    end
  end
endmodule

module TopModule (
  input  [5:0] y,
  input        w,
  output       Y1,
  output       Y3
);
reg [1:0] Y2;
  reg [1:0] Y4;
  initial
    begin
      Y2 = 2'b00;
      Y4 = 2'b00;
    end
  always @ (y, w)
    begin
      if (y[5:0] == 000001)
        begin
          Y2 = 2'b00;
          Y4 = 2'b00;
        end
      else if (y[5:0] == 000010)
        begin
          Y2 = 2'b00;
          Y4 = 2'b01;
        end
      else if (y[5:0] == 000100)
        begin
          Y2 = 2'b01;
          Y4 = 2'b00;
        end
      else if (y[5:0] == 001000)
        begin
          Y2 = 2'b01;
          Y4 = 2'b01;
        end
      else if (y[5:0] == 010000)
        begin
          Y2 = 2'b10;
          Y4 = 2'b00;
        end
      else if (y[5:0] == 100000)
        begin
          Y2 = 2'b10;
          Y4 = 2'b01;
        end
    end
  assign Y1 = Y2;
  assign Y3 = Y4;
endmodule

module TopModule (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output out
);
always @(*) begin
    case (state)
      2'b00: begin
        next_state = 2'b00;
        out = 1'b0;
      end
      2'b01: begin
        next_state = 2'b01;
        out = 1'b0;
      end
      2'b10: begin
        next_state = 2'b10;
        out = 1'b0;
      end
      2'b11: begin
        next_state = 2'b11;
        out = 1'b1;
      end
    endcase
  end
endmodule

