module top_properties (input logic clock, read, write, ready);
property p_read_write(clock, read, write, ready);
    if (posedge clock) begin
        if (read) begin
            assert (write == 0);
        end
        else begin
            assert (write == 1);
        end
    end
endproperty

property p_write_ready(clock, write, ready);
    if (posedge clock) begin
        if (write) begin
            assert (ready == 1);
        end
    end
endproperty

`ifdef FAIL
    property p_write_ready(clock, write, ready);
        if (posedge clock) begin
            if (write) begin
                assert (ready == 1);
            end
        end
    endproperty
`endif

    assert property (p_read_write(clock, read, write, ready));
    assert property (p_write_ready(clock, write, ready));
`ifdef FAIL
    assert property (p_write_ready(clock, write, ready));
`endif
endmodule

