module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);
reg [WIDTH-1:0]    mem[0:DEPTH-1];
reg                 wr_ptr;
reg                 rd_ptr;
reg                 wr_en;
reg                 rd_en;
reg                 full;
reg                 empty;
reg                 prog_full;
reg                 overflow;
reg                 underflow;

assign data_o = mem[rd_ptr];

always @(posedge clk)
begin
    if (reset_p)
    begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        wr_en <= 0;
        rd_en <= 0;
        full <= 0;
        empty <= 1;
        prog_full <= 0;
        overflow <= 0;
        underflow <= 0;
    end
    else
    begin
        if (wr_en)
        begin
            if (wr_ptr == (DEPTH-1))
            begin
                overflow <= 1;
                underflow <= 0;
            end
            else
            begin
                overflow <= 0;
                underflow <= 0;
            end
            if (prog_full)
            begin
                if (mem[wr_ptr] == data_i)
                begin
                    prog_full <= 0;
                    underflow <= 1;
                end
                else
                begin
                    prog_full <= 1;
                    underflow <= 0;
                end
            end
            else
            begin
                prog_full <= 0;
                underflow <= 0;
            end
            mem[wr_ptr] <= data_i;
            wr_ptr <= wr_ptr + 1;
        end
        if (rd_en)
        begin
            if (rd_ptr == (DEPTH-1))
            begin
                underflow <= 1;
                overflow <= 0;
            end
            else
            begin
                underflow <= 0;
                overflow <= 0;
            end
            if (prog_full)
            begin
                if (mem[rd_ptr] == data_i)
                begin
                    prog_full <= 0;
                    overflow <= 1;
                end
                else
                begin
                    prog_full <= 1;
                    overflow <= 0;
                end
            end
            else
            begin
                prog_full <= 0;
                overflow <= 0;
            end
            rd_ptr <= rd_ptr + 1;
        end
    end
end

assign full = (wr_ptr == rd_ptr);
assign empty = (wr_ptr == rd_ptr + 1);
assign prog_full = (wr_ptr - rd_ptr) >= PROG_FULL;

endmodule

