module tone(
    input CLK,
    input[31:0] period, 
    output reg tone_out
    );
parameter CLK_F = 32;
    reg[31:0] prescaler;
    reg[31:0] main_counter;
    initial tone_out = 0;
    always @(posedge CLK) begin
        if(prescaler == 0) begin
            prescaler <= CLK_F - 1;
            main_counter <= 0;
        end else begin
            prescaler <= prescaler - 1;
            if(main_counter == period) begin
                tone_out <= ~tone_out;
                main_counter <= 0;
            end else begin
                main_counter <= main_counter + 1;
            end
        end
    end
endmodule

