module pes_elevator (request_floor, in_current_floor, clk, reset, complete, direction, 
over_time, over_weight, weight_alert, door_alert, out_current_floor) ;


input [7:0]request_floor; 
input [7:0]in_current_floor; 
input clk; 
input reset; 
input over_time; 
input over_weight; 



output direction; 
output complete;
output door_alert;
output weight_alert;
output [7:0] out_current_floor;
reg [7:0] out_current_floor; 
reg direction; 
reg complete; 
reg door_alert; 
reg weight_alert; 



always @(posedge clk or posedge reset) begin
if (reset == 1'b1) begin
out_current_floor <= in_current_floor;
direction <= 1'b0;
complete <= 1'b0;
door_alert <= 1'b0;
weight_alert <= 1'b0;
end else begin
if (over_time == 1'b1) begin
out_current_floor <= out_current_floor;
direction <= 1'b0;
complete <= 1'b0;
door_alert <= 1'b1;
weight_alert <= 1'b0;
end else if (over_weight == 1'b1) begin
out_current_floor <= out_current_floor;
direction <= 1'b0;
complete <= 1'b0;
door_alert <= 1'b0;
weight_alert <= 1'b1;
end else begin
if (request_floor > out_current_floor) begin
out_current_floor <= out_current_floor + 1;
direction <= 1'b1;
complete <= 1'b0;
door_alert <= 1'b0;
weight_alert <= 1'b0;
end else if (request_floor < out_current_floor) begin
out_current_floor <= out_current_floor - 1;
direction <= 1'b0;
complete <= 1'b0;
door_alert <= 1'b0;
weight_alert <= 1'b0;
end else begin
out_current_floor <= out_current_floor;
direction <= 1'b0;
complete <= 1'b1;
door_alert <= 1'b0;
weight_alert <= 1'b0;
end
end
end
end


endmodule

module dualportram #( parameter WIDTH = 64, parameter DEPTH = 6 ) ( input wire clk_a, input wire we_a, input wire [DEPTH-1:0] addr_a, input wire [WIDTH-1:0] din_a, output reg [WIDTH-1:0] dout_a, input wire clk_b, input wire we_b, input wire [DEPTH-1:0] addr_b, input wire [WIDTH-1:0] din_b, output reg [WIDTH-1:0] dout_b );
reg [WIDTH-1:0] memarray [DEPTH-1:0];
always @(posedge clk_a) begin
    if (we_a) begin
      memarray[addr_a] <= din_a;
      dout_a <= memarray[addr_a];
    end
    else begin
      dout_a <= memarray[addr_a];
    end
  end
always @(posedge clk_b) begin
    if (we_b) begin
      memarray[addr_b] <= din_b;
      dout_b <= memarray[addr_b];
    end
    else begin
      dout_b <= memarray[addr_b];
    end
  end
endmodule

module sirv_mrom # (
    parameter AW = 12,
    parameter DW = 32,
    parameter DP = 1024
)(
  input  [AW-1:2] rom_addr, 
  output [DW-1:0] rom_dout  
  );
reg [DW-1:0] rom [DP-1:0];

  initial begin
    for (int i = 0; i < DP; i = i + 1) begin
      if (i == 0) begin
        rom[i] = 32'h00000000;
      end
      else if (i == 1) begin
        rom[i] = 32'h00000001;
      end
      else begin
        rom[i] = 32'h00000000;
      end
    end
  end

  assign rom_dout = rom[rom_addr];
endmodule

