module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
);
parameter [3:0] NUM_STATES = 4;
reg [3:0] current_state;
reg [3:0] next_state;
initial
begin
current_state = 0;
end
always @(posedge clk)
begin
if (resetn == 1'b0)
begin
current_state <= 0;
end
else
begin
current_state <= next_state;
end
end
always @*
begin
case (current_state)
0: begin
if (go == 1'b1)
begin
next_state = 1;
WDATA <= data;
end
else
begin
next_state = 0;
WDATA <= 0;
end
end
1: begin
if (WREADY == 1'b1)
begin
next_state = 2;
end
else
begin
next_state = 1;
end
end
2: begin
if (WREADY == 1'b0)
begin
next_state = 3;
end
else
begin
next_state = 2;
end
end
3: begin
WDATA <= 0;
WSTRB <= 0;
WVALID <= 0;
done <= 1;
next_state = 0;
end
default: begin
next_state = 0;
end
endcase
end
endmodule

