  assign src0_rdy_o = src0_rdy;
  assign src1_rdy_o = src1_rdy;
  assign dst_rdy_o = dst0_rdy_i || dst1_rdy_i;
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      data0 <= 36'h0;
      data1 <= 36'h0;
      src0_rdy <= 1'b0;
      src1_rdy <= 1'b0;
      eof <= 1'b0;
    end else begin
      case (state)
        2'b00: begin
          if (src_rdy_i) begin
            if (data_i[35:0] == match_data) begin
              data0 <= data_i;
              data1 <= 36'h0;
              src0_rdy <= 1'b1;
              src1_rdy <= 1'b0;
              eof <= 1'b0;
              state <= 2'b01;
