              data0 <= 36'h0;
              data1 <= 36'h0;
              src0_rdy <= 1'b0;
              src1_rdy <= 1'b0;
              eof <= 1'b0;
              state <= 2'b00;
            end
          end else begin
            data0 <= 36'h0;
            data1 <= 36'h0;
            src0_rdy <= 1'b0;
            src1_rdy <= 1'b0;
            eof <= 1'b0;
            state <= 2'b00;
          end
        end
        2'b01: begin
          if (src_rdy_i) begin
            if (data_i[35:0] == match_data) begin
              data0 <= 36'h0;
              data1 <= data_i;
              src0_rdy <= 1'b0;
              src1_rdy <= 1'b1;
              eof <= 1'b0;
              state <= 2'b10;
            end else begin
              data0 <= 36'h0;
              data1 <= 36'h0;
              src0_rdy <= 1'b0;
              src1_rdy <= 1'b0;
              eof <= 1'b0;
              state <= 2'b01;
            end
          end else begin
            data0 <= 36'h0;
            data1 <= 36'h0;
            src0_rdy <= 1'b0;
            src1_rdy <= 1'b0;
            eof <= 1'b0;
            state <= 2'b01;
          end
        end
        2'b10: begin
          if (src_rdy_i) begin
            if (data_i[35:0] == match_data) begin
              data0 <= 36'h0;
              data1 <= 36'h0;
              src0_rdy <= 1'b0;
              src1_rdy <= 1'b0;
              eof <= 1'b1;
              state <= 2'b11;
            end else begin
              data0 <= 36'h0;
              data1 <= 36'h0;
              src0_rdy <= 1'b0;
              src1_rdy <= 1'b0;
              eof <= 1'b0;
              state <= 2'b10;
            end
          end else begin
            data0 <= 36'h0;
            data1 <= 36'h0;
            src0_rdy <= 1'b0;
            src1_rdy <= 1'b0;
            eof <= 1'b0;
            state <= 2'b10;
          end
        end
        2'b11: begin
          if (src_rdy_i) begin
            if (data_i[35:0] == match_data) begin
              data0 <= 36'h0;
              data1 <= 36'h0;
              src0_rdy <= 1'b0;
              src1_rdy <= 1'b0;
              eof <= 1'b0;
              state <= 2'b00;
            end else begin
              data0 <= 36'h0;
              data1 <= 36'h0;
              src0_rdy <= 1'b0;
              src1_rdy <= 1'b0;
              eof <= 1'b0;
