    input   wire [6:0]      i_bru_cmd,
    input   wire [1:0]      i_bagu_cmd,
    output  wire [1:0]      o_bp_pattern,
    output  wire            o_bp_taken,
    output  wire            o_bp_hit,
    output  wire [31:0]     o_bp_target,
    output  wire            o_valid,
    output  wire [31:0]     o_pc,
    output  wire [31:0]     o_src0_value,
    output  wire [31:0]     o_src1_value,
    output  wire [3:0]      o_dst_rob,
    output  wire [25:0]     o_imm,
    output  wire [7:0]      o_fid,
    output  wire [6:0]      o_bru_cmd,
    output  wire [1:0]      o_bagu_cmd
);
reg [1:0]      valid_R;
    reg            bp_taken_R;
    reg            bp_hit_R;
    reg [31:0]     bp_target_R;
    reg            valid;
    reg [31:0]     pc;
    reg [31:0]     src0_value;
    reg [31:0]     src1_value;
    reg [3:0]      dst_rob;
    reg [25:0]     imm;
    reg [7:0]      fid;
    reg [6:0]      bru_cmd;
    reg [1:0]      bagu_cmd;

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            valid_R <= 0;
            bp_taken_R <= 0;
            bp_hit_R <= 0;
            bp_target_R <= 0;
        end else begin
            valid_R <= i_valid;
            bp_taken_R <= i_bp_taken;
            bp_hit_R <= i_bp_hit;
            bp_target_R <= i_bp_target;
        end
    end

    always @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            valid <= 0;
            pc <= 0;
            src0_value <= 0;
            src1_value <= 0;
            dst_rob <= 0;
            imm <= 0;
            fid <= 0;
            bru_cmd <= 0;
            bagu_cmd <= 0;
        end else begin
            if (i_valid) begin
                valid <= i_valid;
                pc <= i_pc;
                src0_value <= i_src0_value;
                src1_value <= i_src1_value;
                dst_rob <= i_dst_rob;
                imm <= i_imm;
                fid <= i_fid;
                bru_cmd <= i_bru_cmd;
                bagu_cmd <= i_bagu_cmd;
            end
        end
    end

    assign o_bp_pattern = bp_pattern_R;
    assign o_bp_taken = bp_taken_R;
    assign o_bp_hit = bp_hit_R;
    assign o_bp_target = bp_target_R;
    assign o_valid = valid;
    assign o_pc = pc;
    assign o_src0_value = src0_value;
