module sqrt_pipelined
  #(
    parameter
    INPUT_BITS   = 16, 
    OUTPUT_BITS  = INPUT_BITS / 2 + INPUT_BITS % 2 
    )
  (
   input                        clk,        
   input                        reset_n,    
   input                        start,      
   input [INPUT_BITS-1:0]       radicand,   
   output reg                   data_valid, 
   output reg [OUTPUT_BITS-1:0] root        
   );
reg [OUTPUT_BITS-1:0] start_gen, radicand_gen, root_gen;
reg [OUTPUT_BITS-1:0] mask_gen;
genvar i;
generate
  for (i = 0; i < OUTPUT_BITS; i = i + 1)
  begin
    always @(posedge clk, posedge reset_n)
    begin
      if (reset_n == 1'b0)
      begin
        start_gen <= 1'b0;
        radicand_gen <= 1'b0;
        root_gen <= 1'b0;
        mask_gen <= 1'b0;
      end
      else if (start == 1'b1)
      begin
        start_gen <= 1'b1;
        radicand_gen <= radicand;
        root_gen <= root;
        mask_gen <= mask_gen;
      end
      else
      begin
        start_gen <= 1'b0;
        radicand_gen <= radicand_gen;
        root_gen <= root_gen;
        mask_gen <= mask_gen;
      end
    end
  end
endgenerate
assign data_valid = start_gen;
assign root = root_gen;
endmodule

