module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg load_p1;
reg load_p2;
reg load_p1_from_p2;

always @(posedge clk) begin
    if (reset) begin
        data_p1 <= 0;
        data_p2 <= 0;
        load_p1 <= 0;
        load_p2 <= 0;
        load_p1_from_p2 <= 0;
    end else begin
        if (s_valid) begin
            if (load_p1_from_p2) begin
                data_p1 <= data_p2;
                load_p1_from_p2 <= 0;
            end
            data_p1 <= s_data;
            load_p1 <= 1;
        end
        if (m_ready) begin
            if (load_p1) begin
                data_p2 <= data_p1;
                load_p1 <= 0;
            end
            load_p2 <= 1;
        end
        if (m_valid) begin
            if (load_p2) begin
                m_data <= data_p1;
                load_p2 <= 0;
            end
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        s_ready <= 0;
        m_valid <= 0;
    end else begin
        if (s_valid) begin
            s_ready <= 1;
        end
        if (m_ready) begin
            m_valid <= 1;
        end
    end
end

endmodule

