module alu
  (
   alu_src1,
   alu_src2,
   alu_opcode,
   minus_is_zero,
   less_than,
   less_than_unsigned,
   alu_result
   );
input wire [31:0]       alu_src1;
   input wire [31:0]	   alu_src2;
   input wire [3:0]	   alu_opcode;
   output reg [31:0]	   alu_result;
   output reg		   minus_is_zero;
   output reg		   less_than;
   output reg		   less_than_unsigned;
`define ALU_ADD 0
`define ALU_SUB 1
`define ALU_OR  2
`define ALU_AND 3
`define ALU_XOR 4
`define ALU_LSHL 5
`define ALU_LSHR 6
`define ALU_RSHL 7
`define ALU_RSHR 8
`define ALU_SLL  9
`define ALU_SRL  10
`define ALU_SRA  11
`define ALU_NOP 12

   reg [32:0] alu_internal;
   initial
   begin
      alu_internal = 33'd0;
   end

   always @*
   begin
      case (alu_opcode)
         `ALU_ADD: alu_result = alu_src1 + alu_src2;
         `ALU_SUB: alu_result = alu_src1 - alu_src2;
         `ALU_OR: alu_result = alu_src1 | alu_src2;
         `ALU_AND: alu_result = alu_src1 & alu_src2;
         `ALU_XOR: alu_result = alu_src1 ^ alu_src2;
         `ALU_LSHL: alu_result = alu_src1 << alu_src2;
         `ALU_LSHR: alu_result = alu_src1 >> alu_src2;
         `ALU_RSHL: alu_result = alu_src1 >>> alu_src2;
         `ALU_RSHR: alu_result = alu_src1 << alu_src2;
         `ALU_SLL: alu_result = alu_src1 << alu_src2;
         `ALU_SRL: alu_result = alu_src1 >> alu_src2;
         `ALU_SRA: alu_result = alu_src1 >>> alu_src2;
         `ALU_NOP: alu_result = alu_src1;
      endcase
   end

   always @*
   begin
      alu_internal = alu_result;
   end

   always @*
   begin
      if (alu_internal < 0)
      begin
         minus_is_zero = 1'b1;
      end
      else
      begin
         minus_is_zero = 1'b0;
      end
   end

   always @*
   begin
      if (alu_src1 < alu_src2)
      begin
         less_than = 1'b1;
      end
      else
      begin
         less_than = 1'b0;
      end
   end

   always @*
   begin
      if (alu_src1 < alu_src2)
      begin
         less_than_unsigned = 1'b1;
      end
      else
      begin
         less_than_unsigned = 1'b0;
      end
   end

endmodule

