	input CLK, 
	input [31:0] Divisor, 
	input [31:0] Divider,
	output [31:0] result, 
	output [31:0] remainder,
	inout done 
    );
reg [31:0] Divisor, Divider, remainder, result;
reg [31:0] counter;
reg done;
initial
begin
	Divisor = 0;
	Divider = 0;
	remainder = 0;
	result = 0;
	counter = 0;
	done = 0;
end
always @(posedge CLK)
begin
	if(Divisor != 0 && Divider != 0)
	begin
		if(Divisor > remainder)
		begin
			remainder = remainder - Divider;
			result = result + 1;
		end
		else
		begin
			Divisor = 0;
			Divider = 0;
			remainder = 0;
			result = 0;
			counter = 0;
			done = 1;
		end
	end
end
endmodule

