    input   wire    [3:0]   WE;
    input   wire            EN;
    input   wire    [31:0]  Di;
    output  wire     [31:0]  Do;
    input   wire    [11:0]   A;
reg     wire    [31:0]  r_A;
    reg     wire    [31:0]  Temp_D;
    assign Do = Temp_D;
    always @(posedge CLK)
    begin
        if (EN)
        begin
            Temp_D <= r_A;
        end
