                    Temp_D[7:0] <= r_A[7:0];
                end
            end
        end
    end
    always @(posedge CLK)
    begin
        if (EN)
        begin
            r_A <= Di;
        end
    end
endmodule

module uds_counter(up, down, set, in, out, clk);
	input [WIDTH-1:0] in;
	input up, down, set, clk;
	output reg [WIDTH-1:0] out;
parameter WIDTH = 8;
	parameter MAX = 2**WIDTH-1;
	assign uds = {WIDTH-1{1'b0}}, up, down, set;
	always @(posedge clk) begin
		if(up) begin
			out <= in;
		end else if(set) begin
			if(out == MAX) begin
				out <= 0;
			end else begin
				out <= out + 1;
			end
		end else if(down) begin
			if(out == 0) begin
				out <= MAX;
			end else begin
				out <= out - 1;
			end
		end else begin
			out <= out;
		end
	end
	initial begin
		out <= 0;
	end
endmodule

