module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);
reg [3*NBITS-1:0] rdata_reg [0 :3];
  assign hrdata = rdata_reg[0] | rdata_reg[1] | rdata_reg[2] | rdata_reg[3];
  always @(posedge hclk) begin
    if (hresetn == 1'b0) begin
      rdata_reg[0] <= 0;
      rdata_reg[1] <= 0;
      rdata_reg[2] <= 0;
      rdata_reg[3] <= 0;
    end else begin
      if (valid_rd == 1'b1) begin
        rdata_reg[0] <= rdata[0 : (NUM_RDATA/4)-1];
        rdata_reg[1] <= rdata[(NUM_RDATA/4) : (NUM_RDATA/2)-1];
        rdata_reg[2] <= rdata[(NUM_RDATA/2) : (3*NUM_RDATA/4)-1];
        rdata_reg[3] <= rdata[(3*NUM_RDATA/4) : NUM_RDATA-1];
      end
    end
  end
endmodule

