    output reg [7:0] data
);
reg [15:0] mem0 [0:16383];
    reg [15:0] mem1 [0:16383];
    reg [15:0] mem2 [0:16383];
    initial begin
        $readmemh("data0.bin", mem0);
        $readmemh("data1.bin", mem1);
        $readmemh("data2.bin", mem2);
    end
