module table_010101010(input clk, input rst, input [14:0] addr, output reg match);
always @(posedge clk) begin
    casez(addr)
      15'b01010101010101: match <= 1'b1;
      15'b01010101010100: match <= 1'b1;
      default: match <= 1'b0;
    endcase
  end
  always @(posedge clk or posedge rst) begin
    if (rst) match <= 1'b0;
  end
endmodule

