module shift #(
    parameter DATA_WIDTH = 16,
    parameter DATA_TYPE = "unsigned", 
    parameter SHIFT_VALUE = 1,      
    parameter ASYNC = 0,             
    parameter OVERFLOW_WARNING = 1
) (
    input wire clk,
    input wire [DATA_WIDTH-1:0] din,

    output wire [DATA_WIDTH-1:0] dout,
    output wire [1:0] warning
);
reg [DATA_WIDTH-1:0] reg_din;
reg [DATA_WIDTH-1:0] reg_dout;
reg [DATA_WIDTH-1:0] reg_warning;

generate
    if (DATA_TYPE == "signed") begin
        if (ASYNC == 0) begin
            always @(posedge clk) begin
                reg_din <= din;
                reg_dout <= reg_din << SHIFT_VALUE;
                if (OVERFLOW_WARNING == 1) begin
                    if (reg_din[DATA_WIDTH-1] == 1'b1) begin
                        if (reg_din[DATA_WIDTH-2] == 1'b1) begin
                            reg_warning <= 2'b11;
                        end else begin
                            reg_warning <= 2'b01;
                        end
                    end else begin
                        if (reg_din[DATA_WIDTH-2] == 1'b1) begin
                            reg_warning <= 2'b10;
                        end else begin
                            reg_warning <= 2'b00;
                        end
                    end
                end
            end
        end else begin
            reg_din <= din;
            reg_dout <= reg_din << SHIFT_VALUE;
            if (OVERFLOW_WARNING == 1) begin
                if (reg_din[DATA_WIDTH-1] == 1'b1) begin
                    if (reg_din[DATA_WIDTH-2] == 1'b1) begin
                        reg_warning <= 2'b11;
                    end else begin
                        reg_warning <= 2'b01;
                    end
                end else begin
                    if (reg_din[DATA_WIDTH-2] == 1'b1) begin
                        reg_warning <= 2'b10;
                    end else begin
                        reg_warning <= 2'b00;
                    end
                end
            end
        end
    end else begin
        if (ASYNC == 0) begin
            always @(posedge clk) begin
                reg_din <= din;
                reg_dout <= reg_din << SHIFT_VALUE;
                if (OVERFLOW_WARNING == 1) begin
                    if (reg_din[DATA_WIDTH-1] == 1'b1) begin
                        reg_warning <= 2'b11;
                    end else begin
                        reg_warning <= 2'b00;
                    end
                end
            end
        end else begin
            reg_din <= din;
            reg_dout <= reg_din << SHIFT_VALUE;
            if (OVERFLOW_WARNING == 1) begin
                if (reg_din[DATA_WIDTH-1] == 1'b1) begin
                    reg_warning <= 2'b11;
                end else begin
                    reg_warning <= 2'b00;
                end
            end
        end
    end
endgenerate

assign dout = reg_dout;
assign warning = reg_warning;

endmodule

