	end else begin
		Q <= Q + 1;
	end
	end
endmodule

module itg_lib1_gnc_init (
        ap_start,
        ap_done,
        ap_idle,
        ap_ready,
        p_p,
        ap_return,
        ap_rst
);







input   ap_start;
output   ap_done;
output   ap_idle;
output   ap_ready;
input  [7:0] p_p;
output  [31:0] ap_return;
input   ap_rst;
reg   ap_done;
reg   ap_idle;
reg   ap_ready;







