        ap_done <= 1'b1;
        ap_idle <= 1'b0;
        ap_ready <= 1'b1;
    end
end

endmodule

module diffeq_paj_convert (Xinport, Yinport, Uinport, Aport, DXport, Xoutport, Youtport, Uoutport, CLK, reset);
    input[31:0] Xinport; 
    input[31:0] Yinport; 
    input[31:0] Uinport; 
    input[31:0] Aport; 
    input[31:0] DXport; 
    input CLK; 
    input reset; 
    output[31:0] Xoutport; 
    output[31:0] Youtport; 
    output[31:0] Uoutport;
reg[31:0] x_var; 
    reg[31:0] y_var; 
    reg[31:0] u_var; 
    reg[31:0] temp; 
    initial
    begin
        x_var <= 0; 
        y_var <= 0; 
        u_var <= 0; 
    end
    always@(posedge CLK or posedge reset)
    begin
        if (reset == 1)
        begin
            x_var <= 0; 
            y_var <= 0; 
            u_var <= 0; 
        end
        else
        begin
            temp = (x_var + (y_var * DXport)); 
            x_var <= temp; 
            y_var <= (temp * Uinport) + (y_var * (1 - DXport)); 
            u_var <= (y_var * DXport) + (u_var * (1 - DXport)); 
        end
    end
    assign Xoutport = x_var; 
    assign Youtport = y_var; 
    assign Uoutport = u_var; 
endmodule

