module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );
reg [3:0] cnt;
    always @(posedge clk) begin
        if(reset) begin
            cnt <= 4'b0000;
        end
        else begin
            cnt <= cnt + 1;
        end
    end
    assign sseg = {7'b0000000,hex3,hex2,hex1,hex0};
    assign en = {4'b0000,dp[3:0]};
    always @(*) begin
        case(cnt)
            4'b0000: sseg = {7'b0000000,hex3,hex2,hex1,hex0};
            4'b0001: sseg = {7'b0000000,hex3,hex2,hex1,hex0};
            4'b0010: sseg = {7'b0000000,hex3,hex2,hex1,hex0};
            4'b0011: sseg = {7'b0000000,hex3,hex2,hex1,hex0};
            default: sseg = {7'b0000000,hex3,hex2,hex1,hex0};
        endcase
    end
endmodule

module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );
reg [16:0] tmp;
    always @(data_i, shift_i) begin
        case(shift_i)
            2'b00: tmp <= {17{data_i[13]}};
            2'b01: tmp <= {17{data_i[13]}};
            2'b10: tmp <= {17{data_i[13]}};
            2'b11: tmp <= {17{data_i[13]}};
        endcase
    end
    assign data_o = tmp << 0;
endmodule

module decoder_3to8 
    (input [2:0] a,
     input enable,
     output reg [7:0] y
    );
always @(*) begin
        if(enable == 0) begin
            y = 8'b00000000;
        end else begin
            case(a)
                3'b000: y = 8'b00000001;
                3'b001: y = 8'b00000010;
                3'b010: y = 8'b00000100;
                3'b011: y = 8'b00001000;
                3'b100: y = 8'b00010000;
                3'b101: y = 8'b00100000;
                3'b110: y = 8'b01000000;
                3'b111: y = 8'b10000000;
                default: y = 8'b00000000;
            endcase
        end
    end
endmodule

module Data_Memory(input clk, rst, MemWrite, MemRead, mem_to_reg,
input [31:0] addr, write_data, output [31:0] read_data);
reg [31:0] mem[0:31];
initial
begin
    for (int i = 0; i < 32; i = i + 1)
    begin
        mem[i] = 0;
    end
end
always @(posedge clk)
begin
    if (MemWrite)
    begin
        mem[addr] <= write_data;
    end
end
assign read_data = (MemRead) ? mem[addr] : 0;
endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
wire [BITS - 1:0] enable_wires;
assign enable_wires = {ena, enable_wires};
always @ (posedge clk or posedge rst)
    if (rst)
        cnt <= 0;
    else if (ena)
        if (updown)
            cnt <= cnt + 1;
        else
            cnt <= cnt - 1;
assign out = cnt;
assign ovf = (cnt == 2**BITS - 1) ^ (cnt == 0);
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] reg1 = 32'd0;
	always @ (posedge reg1) begin
		for (int i = 0; i < 16; i = i + 1) begin
			if (reg1[31 - i] > 4) begin
				reg1[31 - i] = reg1[31 - i] + 3;
			end
		end
		reg1 = reg1 >> 4;
		b = reg1[31 - 4:31 - 8];
		s = reg1[31 - 8:31 - 12];
		g = reg1[31 - 12:31 - 16];
		q = reg1[31 - 16:31 - 20];
	end
endmodule

