input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg  mainclk;
reg  updateclk;
reg  capture;
reg  update;

always @ (posedge clk or posedge captnupdt or posedge shiftnld) begin
    case (captnupdt & shiftnld)
        2'b10: begin
            updateclk <= clk;
            capture <= 1'b1;
