module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma, undersampled_sigma;
	reg delta;
	wire [31:0] deriv;

	always @(posedge clk, posedge rstn) begin
		if (rstn == 1'b0) begin
			sigma <= 32'b0;
			undersampled_sigma <= 32'b0;
			delta <= 32'b0;
		end else begin
			if (sdi == 1'b1) begin
				if (ock == 1'b1) begin
					sigma <= sigma + delta;
					undersampled_sigma <= undersampled_sigma + delta;
				end else begin
					sigma <= sigma - delta;
					undersampled_sigma <= undersampled_sigma - delta;
				end
			end else begin
				if (ock == 1'b1) begin
					sigma <= sigma - delta;
					undersampled_sigma <= undersampled_sigma - delta;
				end else begin
					sigma <= sigma + delta;
					undersampled_sigma <= undersampled_sigma + delta;
				end
			end
		end
	end

	always @(posedge clk, posedge rstn) begin
		if (rstn == 1'b0) begin
			deriv <= 32'b0;
		end else begin
			if (sdi == 1'b1) begin
				if (signed_data == 1'b1) begin
					deriv <= sigma - undersampled_sigma;
				end else begin
					deriv <= undersampled_sigma - sigma;
				end
			end else begin
				if (signed_data == 1'b1) begin
					deriv <= undersampled_sigma - sigma;
				end else begin
					deriv <= sigma - undersampled_sigma;
				end
			end
		end
	end

	assign dout = signed_data == 1'b1 ? {31{1'b1}} - deriv : deriv;
endmodule

