module Fibonacci_Series
( 
    input wire CLK_IN,
    input wire RST_N,
    output wire [7:0]SEQUENCE
);
reg [7:0]FIB1,FIB2;
    reg [7:0]FIB3;
    initial
    begin
        FIB1=0;
        FIB2=1;
    end
    always @(posedge CLK_IN)
    begin
        if(RST_N==1'b0)
        begin
            FIB1=0;
            FIB2=1;
        end
        else
        begin
            FIB3=FIB1+FIB2;
            FIB1=FIB2;
            FIB2=FIB3;
        end
    end
    assign SEQUENCE=FIB1+FIB2;
endmodule

