module memory(clk, reset, data_op, instruct_addr, data_addr, write_val, instruct_val, read_val); 

  input wire clk;	                   
  input wire reset;
  input wire data_op;
  input wire [31:0]  instruct_addr;               
  input wire [31:0]  data_addr;               
  input wire [31:0] write_val;

  output reg [31:0] instruct_val;
  output reg[31:0] read_val;
reg [31:0] mem [0:511];

  initial begin
    for (int i = 0; i < 11; i = i + 1) begin
      mem[i] = 5;
    end
    instruct_val = 0;
    read_val = 0;
  end

  always @(posedge clk or negedge reset) begin
    if (reset == 1'b0) begin
      instruct_val <= 0;
      read_val <= 0;
    end
    else begin
      instruct_val <= mem[instruct_addr];
      if (data_op == 1'b1) begin
        read_val <= mem[data_addr];
      end
      else begin
        mem[data_addr] <= write_val;
      end
    end
  end

endmodule

