module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
reg [23:0]                          r_rgb;
reg [1:0]                            r_state;
reg [23:0]                          r_count;
reg [23:0]                          r_size;

initial begin
  r_rgb = 0;
  r_state = 2'b00;
  r_count = 0;
  r_size = 0;
end

always @(posedge clk) begin
  if (rst) begin
    r_rgb <= 0;
    r_state <= 2'b00;
    r_count <= 0;
    r_size <= 0;
  end else begin
    case (r_state)
      2'b00: begin
        if (i_ppfifo_rdy[0]) begin
          r_state <= 2'b01;
          r_count <= 0;
          r_rgb <= i_rgb;
        end
      end
      2'b01: begin
        if (i_h_blank) begin
          r_count <= r_count + 1;
          if (r_count == r_size) begin
            r_state <= 2'b10;
          end
        end else begin
          r_rgb <= r_rgb + 1;
          if (r_rgb == 24'h000000) begin
            r_state <= 2'b00;
          end
        end
      end
      2'b10: begin
        o_ppfifo_clk <= clk;
        o_ppfifo_act <= i_ppfifo_rdy;
        o_ppfifo_stb <= 1;
        o_ppfifo_data <= r_rgb;
        if (i_v_blank) begin
          r_state <= 2'b00;
        end
      end
    endcase
  end
end

endmodule

