module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );



	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
reg 	[6:0]	data_reg;
	reg 	data_regnum;
	reg 	data_out_sign;
	reg 	data_ok;



	always @(posedge clk, posedge rst_n) begin
		if(rst_n == 1'b0) begin
			data_reg <= 7'b0;
			data_regnum <= 8'b0;
			data_out_sign <= 1'b0;
			data_ok <= 1'b0;
		end else begin
			if(data_in_sign == 1'b0) begin
				data_reg <= data_reg + data_in;
				data_regnum <= data_regnum + 1'b1;
			end
			if(data_regnum == 8'b10000000) begin
				if(data_reg == 7'b28 || data_reg == 7'b36) begin
					data_ok <= 1'b1;
				end else begin
					data_ok <= 1'b0;
				end
			end
			if(data_valid == 1'b1) begin
				data_out_sign <= 1'b1;
				data_out <= data_out + 1'b1;
			end else begin
				data_out_sign <= 1'b0;
				data_out <= 7'b0;
			end
		end
	end
endmodule

module counter (rstn, clk, up, down, count); input rstn; input clk; input up; input down; output [WIDTH-1:0] count;
parameter WIDTH = 8;
reg [WIDTH-1:0] count_int;
always @(posedge clk) begin
    if (rstn == 1'b0) begin
      count_int <= 0;
    end else begin
      if (up == 1'b1) begin
        count_int <= count_int + 1;
      end else if (down == 1'b1) begin
        count_int <= count_int - 1;
      end
    end
  end
assign count = count_int;
endmodule

module clk_div(
input wire clk_100MHz,
input wire reset,
output wire clk_100Hz
);
reg [31:0] ticks;
wire clk_out;
assign clk_100Hz = clk_out;
always @(posedge clk_100MHz or posedge reset) begin
if (reset) begin
ticks <= 499999;
clk_out <= 0;
end else begin
ticks <= ticks + 1;
if (ticks == 0) begin
clk_out <= ~clk_out;
end
end
end
endmodule

