module DelayLoop(MR,Timeout,Clock) ;
input			MR, Clock;
output reg	Timeout;
reg [26:0]	Counter;
parameter Divider = 100000;
initial
begin
	Timeout = 0;
	Counter = 0;
end
always @(posedge Clock)
begin
	if(MR == 1'b1)
		Counter = 0;
	else
		Counter = Counter + 1;
end
