module TopModule (
    input  a   (16 bits),
    input  b   (16 bits),
    input  c   (16 bits),
    input  d   (16 bits),
    input  e   (16 bits),
    input  f   (16 bits),
    input  g   (16 bits),
    input  h   (16 bits),
    input  i   (16 bits),
    input  sel ( 4 bits),
    output out (16 bits)
);

    assign out[0] = (sel == 0) ? a[0] : 1'b1;
    assign out[1] = (sel == 1) ? b[0] : 1'b1;
    assign out[2] = (sel == 2) ? c[0] : 1'b1;
    assign out[3] = (sel == 3) ? d[0] : 1'b1;
    assign out[4] = (sel == 4) ? e[0] : 1'b1;
    assign out[5] = (sel == 5) ? f[0] : 1'b1;
    assign out[6] = (sel == 6) ? g[0] : 1'b1;
    assign out[7] = (sel == 7) ? h[0] : 1'b1;
    assign out[8] = (sel == 8) ? i[0] : 1'b1;
    assign out[9] = 1'b1;
    assign out[10] = 1'b1;
    assign out[11] = 1'b1;
    assign out[12] = 1'b1;
    assign out[13] = 1'b1;
    assign out[14] = 1'b1;
    assign out[15] = 1'b1;

endmodule

