module TopModule(
    input  y (6 bits),
    input  w,
    output Y1,
    output Y3
);

reg [1:0] Y2;
reg [1:0] Y4;

initial
    begin
        Y2 = 0;
        Y4 = 0;
    end

assign Y1 = 0;
assign Y3 = 0;

always @ (y, w)
    begin
        if (y[5:0] == 000001)
            begin
                if (w == 0)
                    begin
                        Y2 = 0;
                        Y4 = 0;
                    end
                else
                    begin
                        Y2 = 0;
                        Y4 = 1;
                    end
            end
        else if (y[5:0] == 000010)
            begin
                if (w == 0)
                    begin
                        Y2 = 0;
                        Y4 = 0;
                    end
                else
                    begin
                        Y2 = 0;
                        Y4 = 1;
                    end
            end
        else if (y[5:0] == 000100)
            begin
                if (w == 0)
                    begin
                        Y2 = 0;
                        Y4 = 0;
                    end
                else
                    begin
                        Y2 = 0;
                        Y4 = 1;
                    end
            end
        else if (y[5:0] == 001000)
            begin
                if (w == 0)
                    begin
                        Y2 = 0;
                        Y4 = 0;
                    end
                else
                    begin
                        Y2 = 0;
                        Y4 = 1;
                    end
            end
        else if (y[5:0] == 010000)
            begin
                if (w == 0)
                    begin
                        Y2 = 0;
                        Y4 = 0;
                    end
                else
                    begin
                        Y2 = 0;
                        Y4 = 1;
                    end
            end
        else if (y[5:0] == 100000)
            begin
                if (w == 0)
                    begin
                        Y2 = 0;
                        Y4 = 0;
                    end
                else
                    begin
                        Y2 = 0;
                        Y4 = 1;
                    end
            end
    end

endmodule

