module TopModule (
    input  clk,
    input  load,
    input  ena  (  2 bits),
    input  data (100 bits),
    output q    (100 bits)
);

reg [99:0] q;

always @(posedge clk) begin
    if (load) begin
        q <= data;
    end else begin
        if (ena == 2'b01) begin
            q <= {q[99], q[98:0]};
        end else if (ena == 2'b10) begin
            q <= {q[1:99], q[0]};
        end
    end
end

endmodule

