module TopModule (
    input  code (8 bits),
    output out  (4 bits),
    output valid
);

    assign out = 4'h0;
    assign valid = 1'b0;

    always @ (code) begin
        case (code)
            8'h45: begin
                out = 4'h0;
                valid = 1'b1;
            end
            8'h16: begin
                out = 4'h1;
                valid = 1'b1;
            end
            8'h1e: begin
                out = 4'h2;
                valid = 1'b1;
            end
            8'h26: begin
                out = 4'h3;
                valid = 1'b1;
            end
            8'h25: begin
                out = 4'h4;
                valid = 1'b1;
            end
            8'h2e: begin
                out = 4'h5;
                valid = 1'b1;
            end
            8'h36: begin
                out = 4'h6;
                valid = 1'b1;
            end
            8'h3d: begin
                out = 4'h7;
                valid = 1'b1;
            end
            8'h3e: begin
                out = 4'h8;
                valid = 1'b1;
            end
            8'h46: begin
                out = 4'h9;
                valid = 1'b1;
            end
            default: begin
                out = 4'h0;
                valid = 1'b0;
            end
        endcase
    end

endmodule

module TopModule(
    input  clk,
    input  load,
    input  ena,
    input  amount (2 bits),
    input  data (64 bits),
    output q (64 bits)
);

reg [63:0] shifter;

    always @(posedge clk) begin
        if (load) begin
            shifter <= data;
        end else if (ena) begin
            case (amount)
                2'b00: shifter <= {shifter[63:1], shifter[0]};
                2'b01: shifter <= {shifter[63:8], shifter[7:1]};
                2'b10: shifter <= {shifter[63:1], shifter[0]};
                2'b11: shifter <= {shifter[63:8], shifter[7:1]};
            endcase
        end
    end

endmodule

