module TopModule(
    input  clk,
    input  areset,
    input  in,
    output out
);

reg [1:0] state;
  wire [1:0] next_state;
  assign out = state[1];

  always @(posedge clk) begin
    if (areset) begin
      state <= 2'b00;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      2'b00: begin
        next_state = 2'b00;
        if (in == 1'b0) begin
          next_state = 2'b01;
        end
      end
      2'b01: begin
        next_state = 2'b01;
        if (in == 1'b0) begin
          next_state = 2'b00;
        end
      end
      2'b00: begin
        next_state = 2'b00;
        if (in == 1'b1) begin
          next_state = 2'b01;
        end
      end
      2'b01: begin
        next_state = 2'b01;
        if (in == 1'b1) begin
          next_state = 2'b00;
        end
      end
    endcase
  end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  in,
    output out
);

reg [1:0] state = 2'b00;
    wire [1:0] next_state;
    wire out;

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        next_state = state;
        out = 0;
        case (state)
            2'b00: begin
                if (in == 1'b0) begin
                    next_state = 2'b00;
                end else begin
                    next_state = 2'b01;
                end
            end
            2'b01: begin
                if (in == 1'b0) begin
                    next_state = 2'b01;
                end else begin
                    next_state = 2'b00;
                end
            end
            2'b00: begin
                if (in == 1'b0) begin
                    next_state = 2'b00;
                end else begin
                    next_state = 2'b01;
                end
            end
            2'b01: begin
                if (in == 1'b0) begin
                    next_state = 2'b01;
                end else begin
                    next_state = 2'b00;
                end
            end
        endcase
    end

endmodule

module TopModule(
    input  a,
