wire a0_b1_o1;
wire a1_b0_o1;
wire a1_b1_o1;
wire or0_or1_o0;
wire and0_and1_o0;
wire xor0_xor1_o0;

A a0(
    .x(x),
    .y(y),
    .o0(a0_b0_o0),
    .o1(a0_b1_o0)
);

A a1(
