module TopModule(
    input  clk,
    input  x,
    input  y (3 bits),
    output Y0,
    output z
);

reg [2:0] Y;
    assign Y0 = Y[0];
    assign z = Y[1];

    always @(posedge clk) begin
        case(y)
            3'b000: begin
                if(x == 0) begin
                    Y = 3'b000;
                end else begin
                    Y = 3'b001;
                end
            end
            3'b001: begin
                if(x == 0) begin
                    Y = 3'b001;
                end else begin
                    Y = 3'b100;
                end
            end
            3'b010: begin
                if(x == 0) begin
                    Y = 3'b010;
                end else begin
                    Y = 3'b001;
                end
            end
            3'b011: begin
                if(x == 0) begin
                    Y = 3'b001;
                end else begin
                    Y = 3'b010;
                end
            end
            3'b100: begin
                if(x == 0) begin
                    Y = 3'b011;
                end else begin
                    Y = 3'b100;
                end
            end
        endcase
    end

endmodule

