module TopModule (
    input  clk,
    input  load,
    input  data (256 bits),
    output q (256 bits)
);

reg [15:0] q [15:0];

initial begin
    for (int i = 0; i < 16; i = i + 1)
        for (int j = 0; j < 16; j = j + 1)
            q[i][j] = 0;
end

assign q[15] = data[15:0];
assign q[14] = data[31:16];
assign q[13] = data[47:32];
assign q[12] = data[63:48];
assign q[11] = data[79:64];
assign q[10] = data[95:80];
assign q[9] = data[111:96];
assign q[8] = data[127:112];
assign q[7] = data[143:128];
assign q[6] = data[159:144];
assign q[5] = data[175:160];
assign q[4] = data[191:176];
assign q[3] = data[207:192];
assign q[2] = data[223:208];
assign q[1] = data[239:224];
assign q[0] = data[255:240];

always @(posedge clk) begin
    if (load) begin
        for (int i = 0; i < 16; i = i + 1)
            for (int j = 0; j < 16; j = j + 1)
                q[i][j] = data[15 + (i * 16) + j];
    end
    for (int i = 0; i < 16; i = i + 1)
        for (int j = 0; j < 16; j = j + 1)
            q[i][j] = 0;
end

endmodule

