module TopModule(
    input  clk,
    input  resetn,
    input  r (3 bits),
    output g (3 bits)
);

reg [2:0] state;
    reg [2:0] next_state;
    reg [2:0] g;

    always @ (posedge clk) begin
        if (resetn == 0) begin
            state <= 3'b000;
        end else begin
            state <= next_state;
        end
    end

    always @ (posedge clk) begin
        case (state)
            3'b000: begin
                if (r[0] == 1) begin
                    next_state <= 3'b001;
                end else if (r[1] == 1) begin
                    next_state <= 3'b010;
                end else if (r[2] == 1) begin
                    next_state <= 3'b011;
                end else begin
                    next_state <= 3'b000;
                end
            end
            3'b001: begin
                g[0] <= 1;
                next_state <= 3'b000;
            end
            3'b010: begin
                g[1] <= 1;
                next_state <= 3'b000;
            end
            3'b011: begin
                g[2] <= 1;
                next_state <= 3'b000;
            end
        endcase
    end

endmodule

