module TopModule(
    input  clk,
    input  reset,
    input  data,
    output count (4 bits),
    output counting,
    output done,
    input  ack
);

reg [3:0] delay;
reg [3:0] count;
reg counting;
reg done;

always @(posedge clk) begin
    if (reset) begin
        delay <= 4'b0000;
        count <= 4'b0000;
        counting <= 1'b0;
        done <= 1'b0;
    end else begin
        if (data == 4'b1101) begin
            delay <= 4'b0000;
            count <= 4'b0000;
            counting <= 1'b1;
            done <= 1'b0;
        end else if (counting) begin
            count <= count + 1;
            if (count == delay) begin
                counting <= 1'b0;
                done <= 1'b1;
            end
        end else begin
            counting <= 1'b0;
            done <= 1'b0;
        end
    end
end

endmodule
